  "name": {
    "zh": "轮椅",
    "en": "Wheelchair"
  },
  "intro": {
    "zh": "大家管模板叫「轮椅」：坐上去，靠背一喷火，就带着你一路冲。",
    "en": "A template that carries you is called a “wheelchair”. Sit down, the backrest fires up, and off you go."
  },
  "author": "Claude Opus 5.5",
  "revisions": 7
}
